def search_tickets(query, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0422000" if __import__("os").path.isdir("./environment_mix/0422000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_tickets"
    status = "success"
    code_for_log = None
    resp = None

    # Quota/rate setup (no explicit schema provided; implement minimal observable dynamics)
    def _utcnow():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_usage_store():
        meta = _load("meta.json")
        if not isinstance(meta, dict):
            meta = {}
        if "usage" not in meta or not isinstance(meta.get("usage"), dict):
            meta["usage"] = {"requests": 0}
        return meta

    def _enforce_limits(meta):
        # Simple global rate limit: 120 req/min across all tools
        # Simple daily quota: 5000 req/day across all tools
        logs = _load("usage.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= one_min_ago:
                per_min += 1
            if dt >= day_ago:
                per_day += 1

        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_per_day=5000)
        return None

    def _log_request(meta, ok, error_obj=None):
        logs = _load("usage.json")
        if not isinstance(logs, list):
            logs = []
        meta["usage"]["requests"] = int(meta["usage"].get("requests") or 0) + 1
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "timestamp": _utcnow(),
            "ok": bool(ok),
            "status": "success" if ok else "error",
            "error_code": (error_obj or {}).get("error", {}).get("code") if isinstance(error_obj, dict) else None,
            "latency_ms": latency_ms,
        }
        logs.append(row)
        _save("usage.json", logs)
        _save("meta.json", meta)

    # Enforce unknown params check (tool schema doesn't allow extra)
    if _extra:
        meta = _ensure_usage_store()
        lim = _enforce_limits(meta)
        if lim:
            _log_request(meta, False, lim)
            return lim
        e = _err("VALIDATION_ERROR", "Unknown parameter(s) provided.", unknown_params=sorted(list(_extra.keys())))
        _log_request(meta, False, e)
        return e

    meta = _ensure_usage_store()
    lim = _enforce_limits(meta)
    if lim:
        _log_request(meta, False, lim)
        return lim

    # Validate
    if not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string.")
        _log_request(meta, False, e)
        return e
    if query.strip() == "":
        e = _err("VALIDATION_ERROR", "query is required and must not be empty.")
        _log_request(meta, False, e)
        return e

    tickets = _load("tickets.json")
    if not isinstance(tickets, list):
        tickets = []

    q = query.casefold()
    matches = []
    for t in tickets:
        if not isinstance(t, dict):
            continue
        subj = t.get("subject", "")
        if isinstance(subj, str) and q in subj.casefold():
            matches.append(t)

    resp = {
        "tickets": matches,
        "count": len(matches),
        "query": query,
    }
    _log_request(meta, True, None)
    return resp

